INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (4, 'M04.7', 'Exam Question Bank', 7)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What gives the colour of an LED?', '[{"id": "a", "text": "The active element.", "correct": true}, {"id": "b", "text": "The plastic it is encased in.", "correct": false}, {"id": "c", "text": "The type of gas used inside it.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A germanium diode is used for', '[{"id": "a", "text": "rectification.", "correct": true}, {"id": "b", "text": "voltage stabilization.", "correct": false}, {"id": "c", "text": "modulation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Why is a diode put in parallel with an LED?', '[{"id": "a", "text": "To protect it from AC.", "correct": true}, {"id": "b", "text": "So it will work only above a certain voltage.", "correct": false}, {"id": "c", "text": "So it will work only below a certain voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Using a normal digital multimeter diode-test function, how is a junction diode forward biased?', '[{"id": "a", "text": "the positive lead of the ohmmeter is placed on the anode.", "correct": true}, {"id": "b", "text": "it does not matter which terminal the positive lead of the ohmmeter is placed.", "correct": false}, {"id": "c", "text": "the positive lead of the ohmmeter is placed on the cathode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Light Emitting Diodes (LEDs)', '[{"id": "a", "text": "Emit in a relatively narrow, material-dependent spectral band.", "correct": true}, {"id": "b", "text": "Always have very wide viewing angles.", "correct": false}, {"id": "c", "text": "Are always safe below 5 V without current limiting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a semiconductor junction diode, electrons are the minority carriers', '[{"id": "a", "text": "within the P region.", "correct": true}, {"id": "b", "text": "within the N region.", "correct": false}, {"id": "c", "text": "in both the N and P regions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A silicon diode, when compared to a germanium diode has', '[{"id": "a", "text": "a higher forward bias voltage.", "correct": true}, {"id": "b", "text": "the same forward bias voltage.", "correct": false}, {"id": "c", "text": "less forward bias voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A zener diode', '[{"id": "a", "text": "allows current to flow in one direction.", "correct": false}, {"id": "b", "text": "stabilizes voltage at a predetermined level.", "correct": true}, {"id": "c", "text": "acts like a switch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A junction diode', '[{"id": "a", "text": "is similar to a vacuum diode but cannot rectify.", "correct": false}, {"id": "b", "text": "has one p-n junction.", "correct": true}, {"id": "c", "text": "can handle only very small currents.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Reverse bias', '[{"id": "a", "text": "raises the potential barrier.", "correct": true}, {"id": "b", "text": "lowers the potential barrier.", "correct": false}, {"id": "c", "text": "greatly increases the majority carrier current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A diode connected across a relay coil is used to', '[{"id": "a", "text": "dissipate coil spikes on switch off.", "correct": true}, {"id": "b", "text": "allow the coil to energize with only one polarity.", "correct": false}, {"id": "c", "text": "cause a delay in switching on.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Using a normal digital multimeter diode-test function, where is its positive lead placed for forward conduction?', '[{"id": "a", "text": "anode.", "correct": true}, {"id": "b", "text": "cathode.", "correct": false}, {"id": "c", "text": "either anode or cathode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A thyristor has which of the following?', '[{"id": "a", "text": "A positive temperature coefficient.", "correct": false}, {"id": "b", "text": "High resistance when switched off.", "correct": true}, {"id": "c", "text": "High resistance when switched on.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In an LED, what is used to make the colour?', '[{"id": "a", "text": "The plastic lens cover.", "correct": false}, {"id": "b", "text": "The electrons.", "correct": false}, {"id": "c", "text": "The doping material.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'An atom with 5 electrons in its outer shell is part of', '[{"id": "a", "text": "a C type material.", "correct": false}, {"id": "b", "text": "a P type material.", "correct": false}, {"id": "c", "text": "an N type material.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A diode which emits photons when conducting is a', '[{"id": "a", "text": "light emitting.", "correct": true}, {"id": "b", "text": "varactor.", "correct": false}, {"id": "c", "text": "zener.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The electrodes of an SCR are', '[{"id": "a", "text": "gate, cathode, anode.", "correct": true}, {"id": "b", "text": "source, drain, gate.", "correct": false}, {"id": "c", "text": "anode, cathode, source.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What gives an LED its colour?', '[{"id": "a", "text": "A gas.", "correct": false}, {"id": "b", "text": "The cover.", "correct": false}, {"id": "c", "text": "Composition and impurity of the compound.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Forward voltage of a silicon diode is', '[{"id": "a", "text": "1.6v", "correct": false}, {"id": "b", "text": "0.6v", "correct": true}, {"id": "c", "text": "0.2v", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What is the typical volts drop across an LED', '[{"id": "a", "text": "0.2v", "correct": false}, {"id": "b", "text": "0.4v", "correct": false}, {"id": "c", "text": "1.6v", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What diode gives off light photons when forward biased', '[{"id": "a", "text": "LED.", "correct": true}, {"id": "b", "text": "Gunn diode.", "correct": false}, {"id": "c", "text": "Schottky diode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The anode of a diode is connected to a +4V DC supply and the cathode is connected to a +2V DC supply. The diode is', '[{"id": "a", "text": "forward biased not conducting.", "correct": false}, {"id": "b", "text": "reverse biased not conducting.", "correct": false}, {"id": "c", "text": "forward biased conducting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Using electron flow in a diode the current flows from', '[{"id": "a", "text": "Anode to Cathode.", "correct": false}, {"id": "b", "text": "Cathode to Base.", "correct": false}, {"id": "c", "text": "Cathode to Anode.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When a hole diffuses from the p region to the n region', '[{"id": "a", "text": "raises the potential barrier.", "correct": false}, {"id": "b", "text": "it becomes a minority carrier in the n region.", "correct": true}, {"id": "c", "text": "lowers the potential barrier.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A junction diode', '[{"id": "a", "text": "can handle only small currents.", "correct": false}, {"id": "b", "text": "is similar to a vacuum diode but cannot rectify.", "correct": false}, {"id": "c", "text": "has one p-n junction.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A germanium diode', '[{"id": "a", "text": "has a lower forward bias voltage than a silicon diode.", "correct": true}, {"id": "b", "text": "has a higher forward bias voltage than a silicon diode.", "correct": false}, {"id": "c", "text": "has the same forward bias voltage as a silicon diode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What switches off a thyristor?', '[{"id": "a", "text": "Reverse bias gate.", "correct": false}, {"id": "b", "text": "Remove the gate voltage.", "correct": false}, {"id": "c", "text": "Remove supply voltage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When an SCR is switched on it has', '[{"id": "a", "text": "low resistance.", "correct": true}, {"id": "b", "text": "no change in resistance.", "correct": false}, {"id": "c", "text": "high resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What type of pulse is required to switch on an SCR?', '[{"id": "a", "text": "Positive.", "correct": true}, {"id": "b", "text": "Negative.", "correct": false}, {"id": "c", "text": "Positive or negative.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A piece of pure Germanium', '[{"id": "a", "text": "Electrically neutral overall and intrinsic.", "correct": true}, {"id": "b", "text": "Necessarily deficient in electrons and positively charged.", "correct": false}, {"id": "c", "text": "Necessarily in excess of electrons and negatively charged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When a diode is forward biased, current flow is mainly due to the', '[{"id": "a", "text": "germanium bias junction.", "correct": false}, {"id": "b", "text": "majority carriers.", "correct": true}, {"id": "c", "text": "minority carriers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When a diode is forward biased the', '[{"id": "a", "text": "positive lead is connected to both N and P type.", "correct": false}, {"id": "b", "text": "positive lead is connected to the N type and negative to the P type.", "correct": false}, {"id": "c", "text": "positive lead is connected to the P type and negative to the N type.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What are the majority carriers for a forward biased PN junction device?', '[{"id": "a", "text": "Electrons and holes.", "correct": true}, {"id": "b", "text": "Holes.", "correct": false}, {"id": "c", "text": "Electrons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Germanium in its pure state is', '[{"id": "a", "text": "negatively charged.", "correct": false}, {"id": "b", "text": "neutral.", "correct": true}, {"id": "c", "text": "positively charged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Which diode has a lower forward bias voltage?', '[{"id": "a", "text": "Silicon.", "correct": false}, {"id": "b", "text": "Germanium.", "correct": true}, {"id": "c", "text": "Both have the same forward bias voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A thyristor SCR is a', '[{"id": "a", "text": "bi-directional device.", "correct": false}, {"id": "b", "text": "unidirectional device.", "correct": true}, {"id": "c", "text": "multidirectional device.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What is the basic component used for uncontrolled AC-to-DC rectification?', '[{"id": "a", "text": "Thyristor.", "correct": false}, {"id": "b", "text": "Diode.", "correct": true}, {"id": "c", "text": "Transistor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What is an intrinsic material?', '[{"id": "a", "text": "One with added elements.", "correct": false}, {"id": "b", "text": "One with removed elements.", "correct": false}, {"id": "c", "text": "A pure material.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A diode is parallel to an LED in an AC circuit to', '[{"id": "a", "text": "provide correct amount of current for LED when circuit is switched on.", "correct": false}, {"id": "b", "text": "prevent back EMF in the circuit when LED is switched off.", "correct": false}, {"id": "c", "text": "protect LED from AC current when switched on.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a forward biased diode, current is carried by', '[{"id": "a", "text": "majority carriers.", "correct": true}, {"id": "b", "text": "both.", "correct": false}, {"id": "c", "text": "minority carriers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When checking a diode for reverse bias resistance the positive lead goes to', '[{"id": "a", "text": "anode and negative lead to earth.", "correct": false}, {"id": "b", "text": "cathode and negative lead to anode.", "correct": true}, {"id": "c", "text": "anode and negative lead to cathode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Zener diodes are used for', '[{"id": "a", "text": "Current control.", "correct": false}, {"id": "b", "text": "Voltage control.", "correct": true}, {"id": "c", "text": "Temperature control.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Once started conducting an SCR switches off', '[{"id": "a", "text": "When anode current falls below holding current for sufficient recovery time.", "correct": true}, {"id": "b", "text": "Automatically after a fixed time regardless of current.", "correct": false}, {"id": "c", "text": "Only when the anode becomes positive relative to the cathode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a forward biased diode, electrons leave the', '[{"id": "a", "text": "the anode.", "correct": true}, {"id": "b", "text": "the cathode.", "correct": false}, {"id": "c", "text": "the doped area.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Diodes are', '[{"id": "a", "text": "conductors.", "correct": false}, {"id": "b", "text": "semi-conductors.", "correct": true}, {"id": "c", "text": "Insulators.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Which listed number is a plausible illustrative low-frequency open-loop voltage gain for a classic high-gain op amp, rather than a universal average?', '[{"id": "a", "text": "20", "correct": false}, {"id": "b", "text": "200,000.", "correct": true}, {"id": "c", "text": "200.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Tunnel diodes have the following characteristics:', '[{"id": "a", "text": "Heavily doped P-N junction with an extremely narrow depletion region.", "correct": true}, {"id": "b", "text": "Lightly doped P and N regions and a high reverse breakdown voltage.", "correct": false}, {"id": "c", "text": "Lightly doped P region, heavily doped N region and has a fast response time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The capacitance of a varactor diode is', '[{"id": "a", "text": "Decreases nonlinearly as reverse-bias voltage increases.", "correct": true}, {"id": "b", "text": "Is a linear function of applied reverse-bias voltage.", "correct": false}, {"id": "c", "text": "Is set directly by forward-bias voltage during normal varactor operation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A semiconductor doped with an element having a valency of 5 will produce', '[{"id": "a", "text": "an N type material.", "correct": true}, {"id": "b", "text": "either an N type or a P type depending on what type of semiconductor material is used.", "correct": false}, {"id": "c", "text": "a P type material.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'PIN diodes are used mainly for', '[{"id": "a", "text": "Linear power rectifiers only.", "correct": false}, {"id": "b", "text": "RF/microwave switches and controlled RF attenuators.", "correct": true}, {"id": "c", "text": "Voltage-operated mains rectifiers only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When a hole diffuses from a p-region to the n-region it', '[{"id": "a", "text": "becomes a minority carrier in the n-region.", "correct": true}, {"id": "b", "text": "lowers the potential barrier.", "correct": false}, {"id": "c", "text": "raises the potential barrier.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The junction barrier offers opposition to only', '[{"id": "a", "text": "holes in the p-region.", "correct": false}, {"id": "b", "text": "free electrons in the n-region.", "correct": false}, {"id": "c", "text": "majority carriers in both regions.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Avalanche breakdown occurs when', '[{"id": "a", "text": "reverse bias exceeds a certain value.", "correct": true}, {"id": "b", "text": "forward bias exceeds a certain value.", "correct": false}, {"id": "c", "text": "forward current becomes excessive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'If forward bias is increased from zero on a p-n junction, a rapid increase in current flow for a relatively small increase in voltage occurs', '[{"id": "a", "text": "when the flow of minority carriers is sufficient to cause an avalanche breakdown.", "correct": false}, {"id": "b", "text": "when the depletion layer becomes larger than the space charge area.", "correct": false}, {"id": "c", "text": "only after the forward bias exceeds the potential barrier.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A band pass filter excludes frequencies', '[{"id": "a", "text": "below the frequency required only.", "correct": false}, {"id": "b", "text": "above and below the frequency required.", "correct": true}, {"id": "c", "text": "above the frequency required only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In an unbiased p-n junction, current flow is', '[{"id": "a", "text": "zero, because equal but opposite currents are crossing the junction.", "correct": true}, {"id": "b", "text": "zero, because no charges are crossing the junction.", "correct": false}, {"id": "c", "text": "due to the diffusion of minority carriers only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What type of diode when forward biased holes and electrons recombine producing photons?', '[{"id": "a", "text": "LED.", "correct": true}, {"id": "b", "text": "Photodiode.", "correct": false}, {"id": "c", "text": "Gunn.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A zener diode is designed to operate', '[{"id": "a", "text": "Below breakdown while carrying no reverse current.", "correct": false}, {"id": "b", "text": "At arbitrary forward or reverse voltages with no current limit.", "correct": false}, {"id": "c", "text": "In controlled reverse breakdown within its ratings.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A triac is a type of', '[{"id": "a", "text": "thermistor.", "correct": false}, {"id": "b", "text": "transistor.", "correct": false}, {"id": "c", "text": "thyristor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'If a junction diode is reverse biased too far, the output current would', '[{"id": "a", "text": "reverse direction.", "correct": false}, {"id": "b", "text": "cease to flow.", "correct": false}, {"id": "c", "text": "increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When a PN junction is forward biased, it conducts via', '[{"id": "a", "text": "intrinsic carrier.", "correct": false}, {"id": "b", "text": "majority carrier.", "correct": true}, {"id": "c", "text": "minority carrier.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'If the reverse bias voltage across a diode is too high', '[{"id": "a", "text": "load current reduces to zero.", "correct": false}, {"id": "b", "text": "load current increases rapidly.", "correct": true}, {"id": "c", "text": "load current reverses.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'An LED which emits green light uses', '[{"id": "a", "text": "gallium phosphide.", "correct": true}, {"id": "b", "text": "gallium arsenide.", "correct": false}, {"id": "c", "text": "gallium arsenide phosphide.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A photodiode is operated under', '[{"id": "a", "text": "reverse bias conditions.", "correct": true}, {"id": "b", "text": "forward bias conditions.", "correct": false}, {"id": "c", "text": "reverse or forward bias conditions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'To increase capacitance of a varactor diode', '[{"id": "a", "text": "reverse bias voltage is increased.", "correct": false}, {"id": "b", "text": "reverse bias voltage is decreased.", "correct": true}, {"id": "c", "text": "forward bias voltage is decreased.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A bi-directional TRIAC has two SCRs connected in', '[{"id": "a", "text": "series parallel.", "correct": false}, {"id": "b", "text": "inverse parallel.", "correct": true}, {"id": "c", "text": "parallel series.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What polarity of gate-current pulse relative to cathode normally triggers a forward-biased SCR?', '[{"id": "a", "text": "positive or negative pulse.", "correct": false}, {"id": "b", "text": "negative pulse.", "correct": false}, {"id": "c", "text": "positive pulse.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'To decrease the capacitance of a varactor', '[{"id": "a", "text": "reverse bias should be decreased.", "correct": false}, {"id": "b", "text": "forward bias should be increased.", "correct": false}, {"id": "c", "text": "reverse bias should be increased.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A Zener diode is used across the output for a power supply circuit to', '[{"id": "a", "text": "Provide full-wave rectification by itself.", "correct": false}, {"id": "b", "text": "Prevent every form of thermal runaway.", "correct": false}, {"id": "c", "text": "Help regulate the DC output within the circuit operating limits.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'If a diode has gone open circuit in a full wave bridge rectifier, the output frequency ripple is', '[{"id": "a", "text": "the same as the input frequency.", "correct": true}, {"id": "b", "text": "twice the input frequency.", "correct": false}, {"id": "c", "text": "half the input frequency.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a healthy, unfiltered full-wave bridge rectifier, how does ripple frequency compare with input frequency?', '[{"id": "a", "text": "the output is pure DC. Frequency is 0 Hz.", "correct": false}, {"id": "b", "text": "the output frequency is twice the input frequency.", "correct": true}, {"id": "c", "text": "the output voltage is twice the input voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'After passing through a rectifier, alternating current becomes', '[{"id": "a", "text": "smooth direct current.", "correct": false}, {"id": "b", "text": "pulsating direct current.", "correct": true}, {"id": "c", "text": "square wave form current.", "correct": false}]'::jsonb, '{B1,B2}'),
