    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In which direction does the current flow on a PNP transistor when forward biased?', '[{"id": "a", "text": "Emitter to base.", "correct": false}, {"id": "b", "text": "Emitter to collector.", "correct": true}, {"id": "c", "text": "Collector to emitter.", "correct": false}]'::jsonb, '{B1,B2}'),
