    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'On an op-amp symbol, what does the + input mark denote? (Physical pin number is part-specific.)', '[{"id": "a", "text": "positive input DC pin.", "correct": false}, {"id": "b", "text": "non-inverting input.", "correct": true}, {"id": "c", "text": "positive offset null.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A monostable vibrator', '[{"id": "a", "text": "is switched on by a trigger pulse then within a pre-set time will eventually return to its original", "correct": true}, {"id": "b", "text": "uses a trigger pulse to turn on and the same pulse to turn off.", "correct": false}, {"id": "c", "text": "uses one pulse to turn on and another to turn off.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The negative feedback for an op-amp integrator is connected across a', '[{"id": "a", "text": "resistor.", "correct": false}, {"id": "b", "text": "inductor.", "correct": false}, {"id": "c", "text": "capacitor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'kilohms. What is the amplifier gain?', '[{"id": "a", "text": "1000.", "correct": false}, {"id": "b", "text": "1/1000.", "correct": false}, {"id": "c", "text": "-1000.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In an integrated circuit, active, passive and connecting components are', '[{"id": "a", "text": "connected by fine gold wires.", "correct": false}, {"id": "b", "text": "mounted on the outside of the solid block.", "correct": false}, {"id": "c", "text": "embedded within the solid block.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When compared to a system that is constructed on one board, a modular system using Printed Circuit Boards (PCBs) is', '[{"id": "a", "text": "harder to fault find.", "correct": false}, {"id": "b", "text": "more expensive for spares.", "correct": false}, {"id": "c", "text": "easier to fault find.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A conventional printed circuit board (PCB) uses an insulating laminate bonded to what conductor material?', '[{"id": "a", "text": "a thin sheet of copper.", "correct": true}, {"id": "b", "text": "various thicknesses of copper.", "correct": false}, {"id": "c", "text": "a thick sheet of copper.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When removing a microprocessor', '[{"id": "a", "text": "ensure the power is OFF to avoid static discharge.", "correct": false}, {"id": "b", "text": "no damage is done by static discharge.", "correct": false}, {"id": "c", "text": "considerable damage can be done by static discharge.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A decoupling capacitor in a PCB is used to', '[{"id": "a", "text": "minimise transient currents.", "correct": true}, {"id": "b", "text": "pass DC only.", "correct": false}, {"id": "c", "text": "pass AC only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What is the base material of a PCB?', '[{"id": "a", "text": "Insulator.", "correct": true}, {"id": "b", "text": "Semiconductor.", "correct": false}, {"id": "c", "text": "Conductor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a printed circuit board , the surface resistance testing is', '[{"id": "a", "text": "insulation resistance between adjacent printed conductor.", "correct": true}, {"id": "b", "text": "the resistance between the tow inductors.", "correct": false}, {"id": "c", "text": "between the board and the conductor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What are printed circuit boards made of?', '[{"id": "a", "text": "Fibreglass board coated with copper in which circuits are etched.", "correct": true}, {"id": "b", "text": "Synthetic resin board etched with copper.", "correct": false}, {"id": "c", "text": "Matrix board with components soldered on.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The output of a tachogenerator is', '[{"id": "a", "text": "proportional to speed of rotation.", "correct": true}, {"id": "b", "text": "proportional to position.", "correct": false}, {"id": "c", "text": "proportional to acceleration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'AC power to a synchro system is supplied to', '[{"id": "a", "text": "torque transmitter only.", "correct": false}, {"id": "b", "text": "both the torque receiver and torque transmitter.", "correct": true}, {"id": "c", "text": "torque receiver only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A differential synchro', '[{"id": "a", "text": "can be used as either a transmitter or a receiver.", "correct": true}, {"id": "b", "text": "can only be used as a receiver.", "correct": false}, {"id": "c", "text": "can only be used as a transmitter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In the classical two-axis, two-winding-per-member resolver model, how many windings are on rotor and stator?', '[{"id": "a", "text": "3 coils on the rotor and 2 coils on the stator.", "correct": false}, {"id": "b", "text": "2 coils on the rotor and 3 coils on the stator.", "correct": false}, {"id": "c", "text": "2 coils on the rotor and 2 coils on the stator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Using the conventional CT internal-axis reference, what is the null angle between CT rotor and transmitter-defined stator field?', '[{"id": "a", "text": "wired in series.", "correct": false}, {"id": "b", "text": "at 90° to each other.", "correct": true}, {"id": "c", "text": "parallel to each other.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The rotor of a desynn indicator is', '[{"id": "a", "text": "an electromagnet.", "correct": false}, {"id": "b", "text": "a permanent magnet.", "correct": true}, {"id": "c", "text": "an AC magnet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A differential synchro has', '[{"id": "a", "text": "single phase stator, 2 phase rotor.", "correct": false}, {"id": "b", "text": "3 phase stator, 3 phase rotor.", "correct": true}, {"id": "c", "text": "3 phase stator, single phase rotor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When a servomotor has stopped, the rate feedback from a tachogenerator is', '[{"id": "a", "text": "maximum and in phase.", "correct": false}, {"id": "b", "text": "maximum and anti-phase.", "correct": false}, {"id": "c", "text": "zero.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A tachogenerator is usually used for', '[{"id": "a", "text": "angular feedback.", "correct": false}, {"id": "b", "text": "rate feedback.", "correct": true}, {"id": "c", "text": "position feedback.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Differential synchros have', '[{"id": "a", "text": "a transmitter and a receiver.", "correct": true}, {"id": "b", "text": "a transmitter only.", "correct": false}, {"id": "c", "text": "a receiver only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a torque synchro system, the power supply is connected to', '[{"id": "a", "text": "the rotor windings of both the transmitter and receiver.", "correct": true}, {"id": "b", "text": "the stator windings of the transmitter.", "correct": false}, {"id": "c", "text": "the rotor windings of the transmitter only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'To reduce overshoot errors in a synchro', '[{"id": "a", "text": "the gain of the amplifier is increased.", "correct": false}, {"id": "b", "text": "the system will have velocity feedback.", "correct": true}, {"id": "c", "text": "the system will have position feedback.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A synchro transformer is used to', '[{"id": "a", "text": "add the output of two synchro transmitters.", "correct": false}, {"id": "b", "text": "derive an error voltage from a synchro transmitter signal and a shaft position.", "correct": true}, {"id": "c", "text": "obtain a 26 volt AC reference.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Reversal of the complete power to a torque synchro system will', '[{"id": "a", "text": "displace the receiver rotor by 180o.", "correct": false}, {"id": "b", "text": "cause reverse rotation of the receiver rotor.", "correct": false}, {"id": "c", "text": "have no effect.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The power supply to a torque synchro system is', '[{"id": "a", "text": "AC or DC.", "correct": false}, {"id": "b", "text": "AC.", "correct": true}, {"id": "c", "text": "DC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'An open loop system is one which has', '[{"id": "a", "text": "no direct feedback loop.", "correct": true}, {"id": "b", "text": "rate feedback loop.", "correct": false}, {"id": "c", "text": "position feedback only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Mechanical friction in a servo results in', '[{"id": "a", "text": "increased inertia.", "correct": false}, {"id": "b", "text": "increased damping.", "correct": true}, {"id": "c", "text": "reduced gain.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The position feedback signal is', '[{"id": "a", "text": "phase advanced by 90° with respect to the input signal.", "correct": false}, {"id": "b", "text": "in phase with the input demand signal.", "correct": false}, {"id": "c", "text": "in anti-phase with the demand signal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A servo system that overshoots and oscillates is', '[{"id": "a", "text": "under damped.", "correct": true}, {"id": "b", "text": "over damped.", "correct": false}, {"id": "c", "text": "critically damped.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The power supply to a torque synchro system is connected to', '[{"id": "a", "text": "the transmitter rotor only.", "correct": false}, {"id": "b", "text": "the transmitter stator.", "correct": false}, {"id": "c", "text": "the transmitter and receiver rotors.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a toroidal resistance transmitter indicator system, the power supply is connected to', '[{"id": "a", "text": "the resistor slab.", "correct": false}, {"id": "b", "text": "the rotor.", "correct": false}, {"id": "c", "text": "the brushes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When a servo has reached its null and stopped, the velocity feedback is', '[{"id": "a", "text": "maximum and anti-phase.", "correct": false}, {"id": "b", "text": "maximum and in phase.", "correct": false}, {"id": "c", "text": "zero.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The primary purpose of rate feedback in a positional servo system is to', '[{"id": "a", "text": "ensure system linearity.", "correct": false}, {"id": "b", "text": "prevent excessive overshoot.", "correct": true}, {"id": "c", "text": "ensure minimum response time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In an AC rate servo, a steady input will result in the servomotor', '[{"id": "a", "text": "rotating to a new datum position.", "correct": false}, {"id": "b", "text": "rotating at a constant speed.", "correct": true}, {"id": "c", "text": "oscillating about a new datum.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a torque synchro that includes a differential synchro the power supply is connected to', '[{"id": "a", "text": "all three rotors.", "correct": false}, {"id": "b", "text": "the transmitter and receiver rotors only.", "correct": true}, {"id": "c", "text": "the transmitter rotor only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A differential synchro rotor has', '[{"id": "a", "text": "three windings.", "correct": true}, {"id": "b", "text": "two windings.", "correct": false}, {"id": "c", "text": "one winding.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a resolver synchro the stator windings are electrically displaced by', '[{"id": "a", "text": "90°.", "correct": true}, {"id": "b", "text": "180°.", "correct": false}, {"id": "c", "text": "120°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In the classical two-axis resolver arrangement with output taken from two rotor windings, how are those windings displaced?', '[{"id": "a", "text": "two coils at 90°.", "correct": true}, {"id": "b", "text": "one single coil.", "correct": false}, {"id": "c", "text": "three coils at 120°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a speed control servo system (rate control), the purpose of the tachogenerator is', '[{"id": "a", "text": "to make the velocity proportional to servo demand.", "correct": true}, {"id": "b", "text": "to make the deflection proportional to servo demand.", "correct": false}, {"id": "c", "text": "to make it run at constant speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The rotor of a torque synchro indicator is', '[{"id": "a", "text": "supplied with an excitation voltage.", "correct": true}, {"id": "b", "text": "connected in series with the transmitter stator coil.", "correct": false}, {"id": "c", "text": "short circuited.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'To increase the output of a servo amplifier, it is necessary to', '[{"id": "a", "text": "reduce the tacho feedback.", "correct": true}, {"id": "b", "text": "increase the position feedback.", "correct": false}, {"id": "c", "text": "increase the tacho feedback.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Angular displacement of the control coils with respect to the reference coils in a two phase induction motor are', '[{"id": "a", "text": "90°, 270°.", "correct": true}, {"id": "b", "text": "0°, 180°.", "correct": false}, {"id": "c", "text": "90°, 120°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A servomotor having only a tachogenerator as a feedback device will', '[{"id": "a", "text": "vary its speed with input error voltage.", "correct": false}, {"id": "b", "text": "null out at a position dependant upon input error voltage.", "correct": false}, {"id": "c", "text": "have a constant speed for any given input voltage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The null position of a torque synchro system is when', '[{"id": "a", "text": "the TX and TR rotors are parallel to each other.", "correct": true}, {"id": "b", "text": "the TX and TR rotors are 90° to each other.", "correct": false}, {"id": "c", "text": "the TX and TR rotors are 120° to each other.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'An AC tachogenerator stator has', '[{"id": "a", "text": "two windings 180° apart.", "correct": false}, {"id": "b", "text": "three windings 120° apart.", "correct": false}, {"id": "c", "text": "two windings 90° apart.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A closed loop servomechanism', '[{"id": "a", "text": "must only have position feedback.", "correct": false}, {"id": "b", "text": "must have both position and velocity feedback.", "correct": false}, {"id": "c", "text": "can have either position or velocity feedback.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a control synchro system the power supply is connected to the', '[{"id": "a", "text": "transmitter and receiver rotors.", "correct": false}, {"id": "b", "text": "transmitter rotor and amplifier.", "correct": true}, {"id": "c", "text": "receiver rotor and amplifier.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Velocity feedback', '[{"id": "a", "text": "opposes the demand input.", "correct": true}, {"id": "b", "text": "assists the demand input.", "correct": false}, {"id": "c", "text": "prevents dead space errors.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'An increase in velocity feedback will', '[{"id": "a", "text": "decrease the speed the load moves.", "correct": true}, {"id": "b", "text": "have no effect on speed.", "correct": false}, {"id": "c", "text": "increase the speed the load moves.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Rate feedback can be obtained from a', '[{"id": "a", "text": "tachogenerator.", "correct": true}, {"id": "b", "text": "synchro.", "correct": false}, {"id": "c", "text": "potentiometer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Using the conventional CT internal-axis reference, what rotor-to-field angle gives zero control-transformer output?', '[{"id": "a", "text": "at 90° to each other.", "correct": true}, {"id": "b", "text": "wired in series.", "correct": false}, {"id": "c", "text": "parallel to each other.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a control synchro the stator current ceases to flow when the', '[{"id": "a", "text": "CT rotor is at null.", "correct": false}, {"id": "b", "text": "power is removed.", "correct": true}, {"id": "c", "text": "two rotors are aligned.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a rate servo (speed control) the signal into the servo amplifier is', '[{"id": "a", "text": "input voltage plus position feedback voltage.", "correct": false}, {"id": "b", "text": "input voltage plus tachogenerator output.", "correct": false}, {"id": "c", "text": "input voltage minus tachogenerator output.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'To reduce oscillations about a demand position', '[{"id": "a", "text": "the amount of velocity feedback would be increased.", "correct": true}, {"id": "b", "text": "the amount of velocity feedback would be decreased.", "correct": false}, {"id": "c", "text": "the amount of position feedback would be increased.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A differential synchro rotor consists of', '[{"id": "a", "text": "two windings at 90° apart.", "correct": false}, {"id": "b", "text": "one winding parallel to the transmitter rotor.", "correct": false}, {"id": "c", "text": "three windings at 120° apart.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A differential synchro transmitter used for addition has', '[{"id": "a", "text": "the TDX S1 and S3 connections cross connected to the TX.", "correct": false}, {"id": "b", "text": "the TDX S1 and S3 connections cross connected to the TR.", "correct": false}, {"id": "c", "text": "the TDX R1, R3 and S1, S3 connections cross connected to the TX.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Differential transmitters are used to', '[{"id": "a", "text": "add or subtract two electrical signals.", "correct": false}, {"id": "b", "text": "add or subtract a mechanical signal to an electrical synchro signal.", "correct": true}, {"id": "c", "text": "increase the operating speed of the synchro receiver.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When resolving a Cartesian input to a Polar output', '[{"id": "a", "text": "the outputs are two voltages.", "correct": false}, {"id": "b", "text": "the inputs are a shaft angle and a voltage.", "correct": false}, {"id": "c", "text": "the inputs are two voltages.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In the classical two-axis resolver arrangement with rotor output windings, how many output windings are used and at what displacement?', '[{"id": "a", "text": "one single coil.", "correct": false}, {"id": "b", "text": "two coils at 90° to each other.", "correct": true}, {"id": "c", "text": "three coils at 120° to each other.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The output of a resolver synchro is', '[{"id": "a", "text": "dependant upon the position of the rotor only.", "correct": false}, {"id": "b", "text": "proportional to the speed of input rotation.", "correct": false}, {"id": "c", "text": "a function of the rotor position and excitation voltage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The rotor of an autosyn position indicating system is', '[{"id": "a", "text": "a permanent magnet.", "correct": false}, {"id": "b", "text": "spring controlled.", "correct": false}, {"id": "c", "text": "an electromagnet.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The rotor of a magnesyn transmitter is', '[{"id": "a", "text": "a permanent magnet.", "correct": true}, {"id": "b", "text": "an ac electromagnet.", "correct": false}, {"id": "c", "text": "a dc electromagnet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Torque synchro systems are normally used when the', '[{"id": "a", "text": "system accuracy is of extreme importance.", "correct": false}, {"id": "b", "text": "mechanical load is high.", "correct": false}, {"id": "c", "text": "mechanical load is low.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a resolver synchro the stator windings are electrically disposed by', '[{"id": "a", "text": "90°.", "correct": true}, {"id": "b", "text": "120°.", "correct": false}, {"id": "c", "text": "180°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Torque synchro systems are normally used when the', '[{"id": "a", "text": "system accuracy is of extreme importance.", "correct": false}, {"id": "b", "text": "mechanical load is high.", "correct": false}, {"id": "c", "text": "mechanical load is low.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What device transfers one energy type to another?', '[{"id": "a", "text": "Transponder.", "correct": false}, {"id": "b", "text": "Transducer.", "correct": true}, {"id": "c", "text": "Transmitter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Electrical power is supplied to a synchro rotor', '[{"id": "a", "text": "through slip rings.", "correct": true}, {"id": "b", "text": "through a commutator.", "correct": false}, {"id": "c", "text": "directly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a synchro resolver, the stator coils are at what angle in relation to one another?', '[{"id": "a", "text": "45 degrees.", "correct": false}, {"id": "b", "text": "80 degrees.", "correct": false}, {"id": "c", "text": "90 degrees.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a synchro, what is used to convert signals from one form to another?', '[{"id": "a", "text": "Transducer.", "correct": true}, {"id": "b", "text": "Transmitter.", "correct": false}, {"id": "c", "text": "Transformer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A control surface position feedback signal is', '[{"id": "a", "text": "inversely proportional to surface position.", "correct": false}, {"id": "b", "text": "proportional to surface position.", "correct": true}, {"id": "c", "text": "non-linear.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A position gyro will provide', '[{"id": "a", "text": "acceleration feedback.", "correct": false}, {"id": "b", "text": "velocity feedback.", "correct": false}, {"id": "c", "text": "positional feedback.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In velocity feedback the signal is', '[{"id": "a", "text": "out of phase.", "correct": true}, {"id": "b", "text": "in phase.", "correct": false}, {"id": "c", "text": "equal to the error signal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'If velocity feedback in a servo system is above optimum, this will cause', '[{"id": "a", "text": "no effect.", "correct": false}, {"id": "b", "text": "sluggish operation.", "correct": true}, {"id": "c", "text": "hunting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The amount of rate feedback from a tachogenerator is', '[{"id": "a", "text": "proportional to speed.", "correct": true}, {"id": "b", "text": "constant for all servo speeds.", "correct": false}, {"id": "c", "text": "inversely proportional to speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Increasing velocity feedback from optimum will give', '[{"id": "a", "text": "faster performance.", "correct": false}, {"id": "b", "text": "sluggish performance.", "correct": true}, {"id": "c", "text": "no change on the output.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A rate control servo system with a steady input voltage will give', '[{"id": "a", "text": "decreasing speed.", "correct": false}, {"id": "b", "text": "increasing speed.", "correct": false}, {"id": "c", "text": "constant speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'If a position servo is underdamped, what is a usual effect of a suitable increase in correctly phased negative rate feedback?', '[{"id": "a", "text": "sluggish servo operation.", "correct": false}, {"id": "b", "text": "unstable operation.", "correct": false}, {"id": "c", "text": "reduced hunting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'An increase in negative feedback', '[{"id": "a", "text": "decreases system sensitivity.", "correct": true}, {"id": "b", "text": "increases system sensitivity.", "correct": false}, {"id": "c", "text": "will make the driven device continuously rotate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Position feedback is used to', '[{"id": "a", "text": "indicate to the pilot the position of the load.", "correct": false}, {"id": "b", "text": "to prevent control surface oscillations while the surface is being moved.", "correct": false}, {"id": "c", "text": "ensure control surface moves to the demanded position by the controls.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The output from a control transformer is', '[{"id": "a", "text": "torque.", "correct": false}, {"id": "b", "text": "AC voltage.", "correct": true}, {"id": "c", "text": "DC voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The stator output voltages from a synchro resolver are', '[{"id": "a", "text": "3 phase.", "correct": false}, {"id": "b", "text": "AC single phase.", "correct": true}, {"id": "c", "text": "DC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A typical use for resolver synchros is', '[{"id": "a", "text": "fly by wire system.", "correct": false}, {"id": "b", "text": "engine power instrumentation.", "correct": false}, {"id": "c", "text": "in compass comparator units.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What does a resolver do?', '[{"id": "a", "text": "Adds two signals.", "correct": false}, {"id": "b", "text": "Resolves a movement into sine and cosine components.", "correct": false}, {"id": "c", "text": "Resolves a position into sine and cosine components.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'For an ideal critically damped second-order servo initially at rest, what happens after a step demand?', '[{"id": "a", "text": "overshoots once and return back.", "correct": false}, {"id": "b", "text": "not overshoot.", "correct": true}, {"id": "c", "text": "oscillate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a tachogenerator the output voltage is', '[{"id": "a", "text": "inversely proportional to the speed.", "correct": false}, {"id": "b", "text": "zero.", "correct": false}, {"id": "c", "text": "directly proportional to the speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The primary purpose of rate feedback in a positional servo system is to', '[{"id": "a", "text": "ensure system linearity.", "correct": false}, {"id": "b", "text": "prevent excessive overshoot.", "correct": true}, {"id": "c", "text": "ensure minimum response time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a control surface position indicating system the feedback signal is', '[{"id": "a", "text": "in phase with the control surface position.", "correct": false}, {"id": "b", "text": "indirectly proportional to the control surface position.", "correct": false}, {"id": "c", "text": "proportional to the control surface position.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The difference between an open and closed loop is', '[{"id": "a", "text": "error signal.", "correct": false}, {"id": "b", "text": "feedback.", "correct": true}, {"id": "c", "text": "correspondence.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a Desynn indicator system, where is power supplied to?', '[{"id": "a", "text": "Transmitter and indicator.", "correct": false}, {"id": "b", "text": "Indicator only.", "correct": false}, {"id": "c", "text": "Transmitter only.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What does the Desynn indicator rotor consist of?', '[{"id": "a", "text": "Electro magnet.", "correct": false}, {"id": "b", "text": "Permanent Magnet.", "correct": true}, {"id": "c", "text": "Aluminium cored coil.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When a servomotor overshoots after a step input and oscillates it is', '[{"id": "a", "text": "under damped.", "correct": true}, {"id": "b", "text": "over damped.", "correct": false}, {"id": "c", "text": "critically damped.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A reduction from the optimum setting of the velocity feedback in a servo loop could cause', '[{"id": "a", "text": "instability.", "correct": true}, {"id": "b", "text": "slow response.", "correct": false}, {"id": "c", "text": "ow servo gain.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The phase difference between the supplies of a two phase induction motor is', '[{"id": "a", "text": "90°.", "correct": true}, {"id": "b", "text": "180°.", "correct": false}, {"id": "c", "text": "0°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'If the rotor of the receiver in a torque synchro system was prevented from aligning with the transmitter rotor, then', '[{"id": "a", "text": "the transmitter rotor will turn to align with the receiver rotor.", "correct": false}, {"id": "b", "text": "the receiver will hunt.", "correct": false}, {"id": "c", "text": "the receiver will overheat.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'An E&I bar output at datum has', '[{"id": "a", "text": "an imbalance of voltages in the secondary windings.", "correct": false}, {"id": "b", "text": "no induced voltage in the secondary windings.", "correct": false}, {"id": "c", "text": "equal and opposite voltages induced in the secondary.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The result of cross connecting two of the transmission leads in a torque synchro system and then turning the rotor of the transmitter 60° clockwise would be', '[{"id": "a", "text": "the receiver would move 60° clockwise.", "correct": false}, {"id": "b", "text": "the receiver would move 60° anticlockwise.", "correct": true}, {"id": "c", "text": "the receiver would move 120° anticlockwise.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The control windings of a two phase servomotor is supplied with AC voltage of', '[{"id": "a", "text": "variable amplitude, variable phase.", "correct": true}, {"id": "b", "text": "variable phase.", "correct": false}, {"id": "c", "text": "constant amplitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'With the reversal of the connections to the rotor of the transmitter of a torque synchro, the position of the receiver rotor will be', '[{"id": "a", "text": "changed by 120°.", "correct": false}, {"id": "b", "text": "unchanged.", "correct": false}, {"id": "c", "text": "changed by 180°.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The application of a "stick-off" voltage to a control synchro servo system is', '[{"id": "a", "text": "to overcome the effect of static friction.", "correct": false}, {"id": "b", "text": "to overcome the effect of viscous friction.", "correct": false}, {"id": "c", "text": "to prevent alignment to a false null.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A servo system may include a brake, an automatic trim system is one example where a brake is used. The brake is', '[{"id": "a", "text": "applied when trimming is complete to prevent stabilizer creep.", "correct": true}, {"id": "b", "text": "applied during trimming to prevent oscillations about the demand position.", "correct": false}, {"id": "c", "text": "applied during trimming to prevent servo runaway.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a control synchro the stator current ceases to flow when', '[{"id": "a", "text": "the CT rotor is at null.", "correct": false}, {"id": "b", "text": "when power is removed.", "correct": true}, {"id": "c", "text": "when the two rotors are aligned.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The result of reversing the rotor connections to the receiver of a torque synchro system is that the rotor position', '[{"id": "a", "text": "is changed by 180°.", "correct": true}, {"id": "b", "text": "is unchanged.", "correct": false}, {"id": "c", "text": "is changed by 120°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A two phase induction motor used in a servomechanism', '[{"id": "a", "text": "will always require a starter.", "correct": false}, {"id": "b", "text": "runs with no slip.", "correct": false}, {"id": "c", "text": "is self starting under light loads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A hysteresis servo motor is used in a servomechanism because', '[{"id": "a", "text": "it has good starting characteristics.", "correct": true}, {"id": "b", "text": "good speed/voltage relationship.", "correct": false}, {"id": "c", "text": "low inertia.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Reversal of two of the stator connections on a torque synchro receiver would cause', '[{"id": "a", "text": "the transmitter to become the receiver.", "correct": false}, {"id": "b", "text": "the output to move the same direction as the input.", "correct": false}, {"id": "c", "text": "the output to move the reverse direction to the input.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'For speed measurement, what transfer relationship should a tachogenerator output magnitude have with shaft speed?', '[{"id": "a", "text": "exponential.", "correct": false}, {"id": "b", "text": "linear.", "correct": true}, {"id": "c", "text": "sinusoidal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'With a constant input to a speed control servo, the servo motor', '[{"id": "a", "text": "moves to a certain position.", "correct": false}, {"id": "b", "text": "moves at a constant speed.", "correct": true}, {"id": "c", "text": "oscillates, but otherwise does not move.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Critical damping in a servomechanism is', '[{"id": "a", "text": "the point which allows just one overshoot before the load comes to rest.", "correct": false}, {"id": "b", "text": "the amount of damping that results in the load just not oscillating.", "correct": true}, {"id": "c", "text": "the critical damping required for the optimum damping of the servomechanism.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Reverse rotation of a control transformer rotor can be caused by', '[{"id": "a", "text": "connections to the transmitter rotor reversed.", "correct": false}, {"id": "b", "text": "connections between the transformer rotor and the amplifier reversed.", "correct": true}, {"id": "c", "text": "short circuit between two transmission lines.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Which controller addition can reduce steady following-position error to a constant-velocity demand, if appropriately compensated?', '[{"id": "a", "text": "keeping the error detector (summing point) output as low as possible.", "correct": false}, {"id": "b", "text": "introduction of an integrator.", "correct": true}, {"id": "c", "text": "decreasing the coulomb friction in the system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A two phase motor will stop when', '[{"id": "a", "text": "the control phase is reversed.", "correct": false}, {"id": "b", "text": "the reference phase is reversed.", "correct": false}, {"id": "c", "text": "the control phase is zero.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a conventional externally excited AC drag-cup tachogenerator, how do output amplitude and carrier frequency vary with shaft speed?', '[{"id": "a", "text": "variable frequency, constant voltage.", "correct": false}, {"id": "b", "text": "variable frequency, variable voltage.", "correct": false}, {"id": "c", "text": "variable voltage, constant frequency.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'If two of the stator leads are cross connected in a control synchro system, a 25° clockwise rotation of the input rotor would result in the output rotor', '[{"id": "a", "text": "moving 180° to rectify the defect.", "correct": false}, {"id": "b", "text": "moving 25° anticlockwise.", "correct": true}, {"id": "c", "text": "moving 25° clockwise.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Damping in a servomechanism is easier to apply if', '[{"id": "a", "text": "the mechanism is light and has high inertia.", "correct": false}, {"id": "b", "text": "the mechanism is light and has low inertia.", "correct": true}, {"id": "c", "text": "the mechanism is heavy and has high inertia.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'If the electrical connections to the feedback generator in a control synchro system were disconnected, the', '[{"id": "a", "text": "motor would run in the wrong direction.", "correct": false}, {"id": "b", "text": "input signal to the amplifier would reduce.", "correct": false}, {"id": "c", "text": "system would tend to oscillate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'An increase in servo amplifier gain', '[{"id": "a", "text": "increases system response.", "correct": true}, {"id": "b", "text": "reduces tendency to hunt.", "correct": false}, {"id": "c", "text": "reduces the speed of the system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The term "velocity lag" refers to a', '[{"id": "a", "text": "speed error.", "correct": false}, {"id": "b", "text": "acceleration error.", "correct": false}, {"id": "c", "text": "position error.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The rotor of an AC tachogenerator', '[{"id": "a", "text": "rotates at constant speed.", "correct": false}, {"id": "b", "text": "has skewed slots.", "correct": false}, {"id": "c", "text": "has a copper, brass or aluminium cylinder.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A servo system with transient negative velocity feedback', '[{"id": "a", "text": "is damped with little velocity lag.", "correct": true}, {"id": "b", "text": "is underdamped with high velocity lag.", "correct": false}, {"id": "c", "text": "is damped with high velocity lag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'To reverse the direction of rotation of a two phase induction motor', '[{"id": "a", "text": "reverse the polarity of both the control phase and reference phase.", "correct": false}, {"id": "b", "text": "reverse the polarity of the control phase.", "correct": true}, {"id": "c", "text": "shift the reference by 90°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Loss of DC to a servo amplifier causes the motor to', '[{"id": "a", "text": "reverse.", "correct": false}, {"id": "b", "text": "stop.", "correct": true}, {"id": "c", "text": "run continuously.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'An AC servo demand can be converted to drive a DC motor by the introduction of a', '[{"id": "a", "text": "rectifier.", "correct": false}, {"id": "b", "text": "demodulator.", "correct": true}, {"id": "c", "text": "modulator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Synchro indicator systems are used when the indication is required to move', '[{"id": "a", "text": "a fraction of the input distance.", "correct": false}, {"id": "b", "text": "at the same rate as the input.", "correct": true}, {"id": "c", "text": "slower than the input rate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A linear variable differential transformer is used to measure position feedback where', '[{"id": "a", "text": "an output whose phase is related to direction of movement and amplitude linear over a wide", "correct": true}, {"id": "b", "text": "360° of rotation and high angular accuracy is required.", "correct": false}, {"id": "c", "text": "is of limited importance but robust construction and reliability is important.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A low frequency sinusoidal input will cause a closed loop servomechanism load to', '[{"id": "a", "text": "move to a demand position with no overshoot.", "correct": false}, {"id": "b", "text": "move backwards and forwards at the input frequency.", "correct": true}, {"id": "c", "text": "move to a demand position with overshoot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'If a servo amplifier is suffering from drift', '[{"id": "a", "text": "the load would move to a new position, proportional to the drift and then return back to the datum position.", "correct": false}, {"id": "b", "text": "the load would move to a new position, proportional to the drift and stay there.", "correct": true}, {"id": "c", "text": "the load would oscillate about the datum position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a transient velocity feedback circuit, the tachogenerator output is summated with the demand voltage', '[{"id": "a", "text": "at all times when the load is moving.", "correct": false}, {"id": "b", "text": "only when the load is speeding up or slowing down.", "correct": true}, {"id": "c", "text": "only when the load is slowing down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'An LVDT has', '[{"id": "a", "text": "an output winding which is wound in series opposition.", "correct": true}, {"id": "b", "text": "an input winding whose voltage will change with load movement.", "correct": false}, {"id": "c", "text": "an output winding whose voltage and frequency is linear to load angular movement.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'To convert a differential synchro from subtraction to addition you would', '[{"id": "a", "text": "change over two rotor and two stator connections.", "correct": true}, {"id": "b", "text": "change over all three stator windings.", "correct": false}, {"id": "c", "text": "reverse the reference phase supply.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In general the accuracy of a synchro system increases if the', '[{"id": "a", "text": "stator current is low.", "correct": true}, {"id": "b", "text": "rotor current is high.", "correct": false}, {"id": "c", "text": "stator current is high.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The induced signal in the output coils of the magnesyn system', '[{"id": "a", "text": "de-saturates the soft iron core.", "correct": false}, {"id": "b", "text": "is of a value of 800 Hz.", "correct": true}, {"id": "c", "text": "damps the pointer oscillations.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The direction of the induced (secondary) magnetic field in a synchro transmitter', '[{"id": "a", "text": "in the same direction as the primary field.", "correct": false}, {"id": "b", "text": "is in the opposite direction to the primary field.", "correct": true}, {"id": "c", "text": "is 90° to the primary magnetic field.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The cogging effect in synchros is rectified by', '[{"id": "a", "text": "using an elliptical cog.", "correct": false}, {"id": "b", "text": "skewing the rotor.", "correct": true}, {"id": "c", "text": "using carbon brushes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Reversal of the power supply to either the transmitter or the receiver of a torque synchro system would', '[{"id": "a", "text": "make the receiver rotor rotate in the opposite direction.", "correct": false}, {"id": "b", "text": "cause a 180° displacement between the transmitter and the receiver.", "correct": true}, {"id": "c", "text": "have no effect on the indication, but would cause a heavy current to flow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The purpose of a flywheel incorporated in a synchro is to', '[{"id": "a", "text": "increase the driving force.", "correct": false}, {"id": "b", "text": "prevent insect ingress.", "correct": false}, {"id": "c", "text": "prevent oscillations.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a synchro system, if two stator lines are crossed the receiver will', '[{"id": "a", "text": "be 180° out.", "correct": false}, {"id": "b", "text": "not be affected.", "correct": false}, {"id": "c", "text": "reverse direction.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In an E and I signal generator at datum, the voltage on the secondary windings', '[{"id": "a", "text": "is zero.", "correct": false}, {"id": "b", "text": "is maximum.", "correct": false}, {"id": "c", "text": "are equal and opposite.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a synchrotel, the', '[{"id": "a", "text": "stator coil is fixed and the rotor coil moves.", "correct": false}, {"id": "b", "text": "rotor coil and stator coil is fixed.", "correct": true}, {"id": "c", "text": "rotor coil is fixed and the stator coil moves.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'An E&I transformer out of datum has', '[{"id": "a", "text": "equal and opposite voltages in each windings.", "correct": false}, {"id": "b", "text": "unequal and opposite voltages in both windings.", "correct": true}, {"id": "c", "text": "no voltage in either winding.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When is maximum voltage induced into the rotor of a control synchro transformer?', '[{"id": "a", "text": "90 degrees (null position).", "correct": false}, {"id": "b", "text": "0 degrees.", "correct": true}, {"id": "c", "text": "When spinning fast.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'To check the output of a synchro stator it would be preferable to use', '[{"id": "a", "text": "a Valve Voltmeter.", "correct": true}, {"id": "b", "text": "a Cambridge Bridge.", "correct": false}, {"id": "c", "text": "an Avometer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Synchro capacitors are connected into synchro systems to', '[{"id": "a", "text": "act as spark suppression due to wear of the slip rings.", "correct": false}, {"id": "b", "text": "increase the accuracy of the control synchro.", "correct": true}, {"id": "c", "text": "minimize the torque synchro stator current at null.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a slab desynn transmitter the', '[{"id": "a", "text": "pick-offs form part of the circuit resistance.", "correct": false}, {"id": "b", "text": "pick-offs rotate on the slab resister.", "correct": true}, {"id": "c", "text": "pick-offs are connected to a spark suppressor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'If the amplitude of negative velocity feedback falls below its normal level, what can happen to servo damping?', '[{"id": "a", "text": "be sluggish in operation.", "correct": false}, {"id": "b", "text": "oscillate.", "correct": true}, {"id": "c", "text": "be overdamped.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Torque synchro receiver bearing friction will cause', '[{"id": "a", "text": "improved accuracy.", "correct": false}, {"id": "b", "text": "misalignment.", "correct": true}, {"id": "c", "text": "hunting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A control synchro system pointer is', '[{"id": "a", "text": "actuated by a permanent magnet.", "correct": false}, {"id": "b", "text": "displaced by the torque of the stator.", "correct": false}, {"id": "c", "text": "motor driven.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A D.C. signal converted to a phase sensitive A.C. is', '[{"id": "a", "text": "modulation.", "correct": true}, {"id": "b", "text": "demodulation.", "correct": false}, {"id": "c", "text": "phase conversion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The rotor coil of a synchrotel', '[{"id": "a", "text": "rotates only when a current flows in it.", "correct": false}, {"id": "b", "text": "rotates.", "correct": false}, {"id": "c", "text": "is stationary.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The purpose of synchro capacitors in a differential synchro transmission system', '[{"id": "a", "text": "reduce stator circuit impedance.", "correct": false}, {"id": "b", "text": "to reduce stator current.", "correct": true}, {"id": "c", "text": "reduce rotor current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The purpose of a flywheel in a synchro receiver indicator is to', '[{"id": "a", "text": "increase driving torque.", "correct": false}, {"id": "b", "text": "prevent spinning or oscillation.", "correct": true}, {"id": "c", "text": "encourage spinning.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A linear variometer is', '[{"id": "a", "text": "a special synchro giving ac output proportional to shaft angle.", "correct": true}, {"id": "b", "text": "a special auto transformer for synchro system power supplies.", "correct": false}, {"id": "c", "text": "an alternative term for a desynn system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In a synchrotel the rotating winding is', '[{"id": "a", "text": "the stator.", "correct": false}, {"id": "b", "text": "rotor.", "correct": false}, {"id": "c", "text": "neither.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The receiver rotor in a torque synchro system oscillates over an arc of approx 75 degrees. The probable cause is', '[{"id": "a", "text": "one stator line open circuit.", "correct": true}, {"id": "b", "text": "two stator lines reversed.", "correct": false}, {"id": "c", "text": "short circuit between two stator lines.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'Synchro capacitors are fitted', '[{"id": "a", "text": "to improve sensitivity and accuracy.", "correct": true}, {"id": "b", "text": "to provide critical damping.", "correct": false}, {"id": "c", "text": "to make additional damping features unnecessary.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The output of a control transformer is made', '[{"id": "a", "text": "phase and amplitude sensitive by direction and magnitude of the transmitter rotor movement", "correct": true}, {"id": "b", "text": "phase and amplitude sensitive by magnitude and direction of the transmitter rotor movement respectively.", "correct": false}, {"id": "c", "text": "phase sensitive by transmitter rotor excitation and amplitude sensitive by direction of transmitter rotor", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In the military synchro code, what does B immediately after the functional letters (for example CTB) denote?', '[{"id": "a", "text": "that the synchro is second hand.", "correct": false}, {"id": "b", "text": "the modification status.", "correct": false}, {"id": "c", "text": "that the stator is rotatable.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'TX is the abbreviation for a', '[{"id": "a", "text": "torque transmitter.", "correct": true}, {"id": "b", "text": "control transformer.", "correct": false}, {"id": "c", "text": "torque receiver.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'TR is the abbreviation for a', '[{"id": "a", "text": "transmitter Resolver.", "correct": false}, {"id": "b", "text": "torque receiver.", "correct": true}, {"id": "c", "text": "torque synchro.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'When a synchro system is in correspondence, its transmitter and receiver', '[{"id": "a", "text": "are in phase.", "correct": true}, {"id": "b", "text": "are anti-phase.", "correct": false}, {"id": "c", "text": "are at 90° to each other.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'The reference phase to a synchro is', '[{"id": "a", "text": "50 Hz.", "correct": false}, {"id": "b", "text": "28 VDC.", "correct": false}, {"id": "c", "text": "400 Hz.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'In rate feedback, when the motor has reached the commanded position, the output will be', '[{"id": "a", "text": "maximum and in-phase with the input.", "correct": false}, {"id": "b", "text": "maximum and out-of-phase with the input.", "correct": false}, {"id": "c", "text": "zero.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What power is required for a desynn indicator system?', '[{"id": "a", "text": "DC.", "correct": true}, {"id": "b", "text": "AC 400 Hz.", "correct": false}, {"id": "c", "text": "AC 50 Hz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'What material would have 3 electrons in the outermost orbit?', '[{"id": "a", "text": "Majority Carrier material.", "correct": false}, {"id": "b", "text": "The donor to an N-Type semi-conductor material.", "correct": false}, {"id": "c", "text": "The acceptor to a P-Type semi-conductor material.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M04.7'), 'A microprocessor on a PCB', '[{"id": "a", "text": "is not easily damaged by static-electricity.", "correct": false}, {"id": "b", "text": "is easily damaged by static-electricity if mishandling.", "correct": true}, {"id": "c", "text": "is only easily damaged by static-electricity if removed from the PCB.", "correct": false}]'::jsonb, '{B1,B2}'),
